/// (按鍵, 期望的組字區內容)
///
/// 前半是實機回報過的問題，後半是對照組。
const CASES: &[(&str, &str)] = &[
    // 實機回報過的問題（凍結切斷詞的資訊 / 顯示逐單位問）
    ("rup wu0 ", "今天"),
    ("rup wu0 wu0 fu4cp3cl3", "今天天氣很好"),
    ("h0 wu/ ", "餐廳"),
    ("ru04au04", "見面"),
    ("au/6wu0 ", "明天"),
    // 對照組：本來就沒問題的
    ("su3cl3", "你好"),
    ("g42k7", "是的"),
    ("2k7wu0 fu4", "的天氣"),
    ("wu0 fu4cp3cl3", "天氣很好"),
    // 混合語言。
    //
    // **空白要保留**：`check` 後面那個空白是使用者打的，該進到文件裡。
    // 中文之間的空白則不同——那些是被注音當成一聲吃掉的（`u ` = ㄧ+一聲），
    // 不會出現在輸出。
    ("check u vu84", "check 一下"),
    // 標點：`,` 在注音鍵盤上是 ㄝ，兩種解讀都合法。
    // 曾經因為「符號在尾端也建邊」的規則，讓「好ㄝ」贏過「好」+「，」
    // ——一段不必付分段懲罰，即使分數被降到 0.03 也划算。
    ("wu0 fu4cp3cl3,", "天氣很好，"),
    ("su3cl3,", "你好，"),
    // 純英文句子：空白全部要留著。
    ("today is a nice day", "today is a nice day"),
    ("hello world", "hello world"),
    // 大寫縮寫接注音。判準原本是「整段全大寫」，`APIu` 混了小寫就
    // 逃過降分，結果「あぴう」贏過「API」——改成「含大寫」才擋得住。
    ("5k4ek7APIul4wul65/3u vu84", "這個API要調整一下"),
    // 小寫版本沒有 Shift 信號，日文「アピ」贏過英文是可接受的。
    // 但**不能讓日文邊吃掉注音的第一個鍵**——`あぴう` 多吃一個 `u`
    // 之後，後面的 `l4` 只剩「奧」可配，中文跟著壞掉。
    ("5k4ek7apiul4wul65/3u vu84", "這個アピ要調整一下"),
];
